var lastSynchronizationTextElement=document.getElementById("lastSynchronizationText");
var installApplicationButtonElement=document.getElementById("installApplicationButton");
var deferredInstallationPromptEventReference=null;
function loadStoredNoteListFromStorage(){
try{
var storedValue=window.localStorage.getItem(noteStorageKeyName);
if(!storedValue){
return[];
}
var parsedValue=JSON.parse(storedValue);
if(!Array.isArray(parsedValue)){
return[];
}
return parsedValue;
}catch(error){
return[];
}
}
function persistNoteListToStorage(noteList){
try{
var serializedValue=JSON.stringify(noteList);
window.localStorage.setItem(noteStorageKeyName,serializedValue);
updateLastSynchronizationText(new Date());
}catch(error){
}
}
function createNoteIdentifier(){
var timestampPart=Date.now().toString();
var randomPart=Math.floor(Math.random()*1000000).toString();
return timestampPart+"-"+randomPart;
}
function formatDateForDisplay(dateValue){
try{
return dateValue.toLocaleString("hu-HU",{
year:"numeric",
month:"2-digit",
day:"2-digit",
hour:"2-digit",
minute:"2-digit"
});
}catch(error){
return dateValue.toISOString();
}
}
function updateLastSynchronizationText(dateValue){
if(!lastSynchronizationTextElement){
return;
}
var formattedDate=formatDateForDisplay(dateValue);
lastSynchronizationTextElement.textContent="Utolsó mentés: "+formattedDate;
}
function renderNoteList(noteList){
if(!noteListContainerElement||!noteListEmptyStateElement){
return;
}
noteListContainerElement.innerHTML="";
if(!noteList.length){
noteListEmptyStateElement.style.display="block";
return;
}
noteListEmptyStateElement.style.display="none";
var sortedNoteList=noteList.slice().sort(function(firstNote,secondNote){
var firstNoteTime=firstNote.createdAt||firstNote.created_at;
var secondNoteTime=secondNote.createdAt||secondNote.created_at;
return secondNoteTime-firstNoteTime;
});
sortedNoteList.forEach(function(noteItem){
var listItemElement=document.createElement("li");
listItemElement.className="note-list-item";
var headerLineElement=document.createElement("div");
headerLineElement.className="note-list-item-header-line";
var titleTextElement=document.createElement("div");
titleTextElement.className="note-list-item-title-text";
titleTextElement.textContent=noteItem.title||"Névtelen jegyzet";
var metaTextElement=document.createElement("div");
metaTextElement.className="note-list-item-meta-text";
var createdDateValue=new Date(noteItem.createdAt||noteItem.created_at||Date.now());
metaTextElement.textContent=formatDateForDisplay(createdDateValue);
headerLineElement.appendChild(titleTextElement);
headerLineElement.appendChild(metaTextElement);
var bodyTextElement=document.createElement("div");
bodyTextElement.className="note-list-item-body-text";
bodyTextElement.textContent=noteItem.content||"";
var actionsRowElement=document.createElement("div");
actionsRowElement.className="note-list-item-actions-row";
var deleteButtonElement=document.createElement("button");
deleteButtonElement.type="button";
deleteButtonElement.className="note-list-item-delete-button";
var deleteIconElement=document.createElement("span");
deleteIconElement.className="note-list-item-delete-icon";
var deleteLabelElement=document.createElement("span");
deleteLabelElement.textContent="Törlés";
